def sum_of_digits(n):
    """Return the sum of digits of a number."""
    return sum(int(digit) for digit in str(n))

def largest_prime_sum(lst):
    """Find the largest prime value in the list and return the sum of its digits."""
    max_prime = None
    for num in lst:
        if is_prime(num):
            if max_prime is None or num > max_prime:
                max_prime = num
    if max_prime is not None:
        return sum_of_digits(max_prime)
    else:
        return 0

