def match_parens(lst):
    s1, s2 = lst
    open_count = 0
    for c in s1 + s2:
        if c == '(':
            open_count += 1
        elif c == ')':
            if open_count == 0:
                return 'No'
            open_count -= 1
    return 'Yes' if open_count == 0 else 'No'

