def check_if_last_char_is_a_letter(txt):
    # Remove leading and trailing spaces
    txt = txt.strip()

    # If the string is empty, return False
    if not txt:
        return False

    # Split the string into words
    words = txt.split()

    # Get the last word
    last_word = words[-1]

    # If the last word is a single character, return True if it's a letter, False otherwise
    if len(last_word) == 1:
        return last_word.isalpha()

    # If the last word is not a single character, return True if its last character is a letter, False otherwise
    return last_word[-1].isalpha()

