def compare_one(a, b):
    # Try to convert a and b to float
    try:
        a_float = float(a)
        b_float = float(b)
    except ValueError:
        # If a or b cannot be converted to float, return the larger one as is
        if a > b:
            return a
        elif a < b:
            return b
        else:
            return None

    # If a and b can be converted to float, return the larger one
    if a_float > b_float:
        return a_float
    elif a_float < b_float:
        return b_float
    else:
        return None

