def fix_spaces(text):
    text = text.replace("  ", "-")
    while "  " in text:
        text = text.replace("  ", " ")
    return text.replace(" ", "_")

# Test cases
assert fix_spaces("Example") == "Example"
assert fix_spaces("Example 1") == "Example_1"
assert fix_spaces(" Example 2") == "_Example_2"
assert fix_spaces(" Example   3") == "_Example-3"

def file_name_check(file_name):
    # Check if the substring before the dot starts with a letter
    if not file_name.split('.')[0][0].isalpha():
        return 'No'

    # Check if there is exactly one dot in the file name
    if file_name.count('.') != 1:
        return 'No'

    # Check if the substring after the dot is valid
    if file_name.split('.')[1] not in ['txt', 'exe', 'dll']:
        return 'No'

    # Check if there are more than three digits in the file name
    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    return 'Yes'

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num ** 2
        elif i % 4 == 0 and i % 3 != 0:
            total += num ** 3
    return total

